"""Account-data export and deletion compiled from data/contract.json.

The account routes construct this handler with the authenticated account's
runtime persistence, so every query is scoped to the app and the owner the
runtime authenticated. Code renders this file from the per_user collections
the module owns.
"""
from __future__ import annotations

from datetime import date, datetime
from typing import Any

_MODULE_ID = 'task_management'
# per_user collection -> (owner field, declared fields)
_COLLECTIONS: dict[str, tuple[str, tuple[str, ...]]] = {'tasks': ('user_id', ('task_id', 'title', 'description', 'status', 'created_at', 'updated_at', 'user_id'))}
_PAGE_SIZE = 100


def _portable(value: Any) -> Any:
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, dict):
        return {str(key): _portable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_portable(item) for item in value]
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    return str(value)


class AccountDataHandler:
    """Export and delete the account owner's task_management records."""

    def __init__(self, persistence: Any) -> None:
        self.persistence = persistence

    def _collection(self, app_id: str, name: str) -> Any:
        if self.persistence.app_id != app_id:
            raise PermissionError('account persistence is bound to another app')
        return self.persistence.collection(_MODULE_ID, name)

    async def delete_user_data(self, *, app_id: str, user_id: str) -> dict[str, Any]:
        deleted = 0
        for name, (owner_field, _fields) in _COLLECTIONS.items():
            result = await self._collection(app_id, name).delete_many({owner_field: user_id})
            deleted += int(getattr(result, 'deleted_count', 0) or 0)
        return {'deleted_count': deleted}

    async def export_user_data(self, *, app_id: str, user_id: str) -> dict[str, Any]:
        export: dict[str, Any] = {}
        for name, (owner_field, fields) in _COLLECTIONS.items():
            collection = self._collection(app_id, name)
            records: list[dict[str, Any]] = []
            query: dict[str, Any] = {owner_field: user_id}
            while True:
                page = await collection.find_many(query, limit=_PAGE_SIZE, sort=[('_id', 1)])
                records.extend(
                    {field: _portable(record[field]) for field in fields if field in record} for record in page
                )
                if len(page) < _PAGE_SIZE:
                    break
                query = {owner_field: user_id, '_id': {'$gt': page[-1]['_id']}}
            export[f'{_MODULE_ID}_{name}'] = records
        return export

from . import service

