"""Ownership preflight compiled from data/contract.json.

Runtime persistence enforces ownership independently of these helpers.
"""

_SCOPES = {'tasks': ('user_id', 'user_id')}


def _scope(context, entity_name):
    if entity_name is None:
        if len(_SCOPES) != 1:
            raise ValueError('entity_name is required for a module with multiple collections')
        entity_name = next(iter(_SCOPES))
    if entity_name not in _SCOPES:
        raise ValueError(f'Undeclared policy collection: {entity_name!r}')
    persistence = getattr(context, 'persistence', None)
    app_id = getattr(persistence, 'app_id', None)
    if not isinstance(app_id, str) or not app_id.strip():
        raise PermissionError('Missing required scope identity: app_id')
    field, attribute = _SCOPES[entity_name]
    if attribute is None:
        return app_id, None, None
    principal = getattr(persistence, 'principal', None)
    user_id = principal.user_id if principal is not None else None
    if not isinstance(user_id, str) or not user_id.strip():
        raise PermissionError('Missing required scope identity: user_id')
    identity = user_id if attribute == 'user_id' else principal.workspace_id
    if not isinstance(identity, str) or not identity.strip():
        raise PermissionError(f'Missing required scope identity: {attribute}')
    return app_id, field, identity


def scoped_query(context, filters=None, *, entity_name=None):
    _, field, identity = _scope(context, entity_name)
    query = dict(filters or {})
    query.pop('app_id', None)
    if field is not None:
        query[field] = identity
    return query


def scope_record(context, record, *, entity_name=None):
    app_id, field, identity = _scope(context, entity_name)
    scoped = {**dict(record), 'app_id': app_id}
    if field is not None:
        if field in scoped and scoped[field] != identity:
            raise PermissionError('Record owner disagrees with authenticated principal')
        scoped[field] = identity
    return scoped

